{
  "id": null,
  "uid": "mxl-fabric",
  "title": "MXL Fabric",
  "description": "Fabric ports, links and mirror placement of mxl-k8s: what placement committed per port against the ceilings in force, what the links carry, link health, and per-mirror delivery.",
  "tags": [
    "mxl",
    "fabric",
    "operator-managed"
  ],
  "timezone": "browser",
  "editable": false,
  "graphTooltip": 1,
  "schemaVersion": 38,
  "version": null,
  "refresh": "15s",
  "time": {
    "from": "now-30m",
    "to": "now"
  },
  "fiscalYearStartMonth": null,
  "liveNow": null,
  "links": [
    {
      "type": "dashboards",
      "tags": [
        "mxl"
