        "name": "Link state changes",
        "enable": true,
        "iconColor": "orange",
        "datasource": {
          "type": "prometheus",
          "uid": "prometheus"
        },
        "expr": "changes(mxl_gateway_link_up{node=~\"$node\",link=~\"$link\"}[2m]) > 0",
        "titleFormat": "Link state changed",
        "textFormat": "{{node}} {{link}}",
        "step": "60s"
      }
    ]
  },
