          "datasource": {
            "type": "prometheus",
            "uid": "prometheus"
          },
          "expr": "sum(8 * (sum by (node, link) (rate(mxl_gateway_link_transmitted_bytes_total{node=~\"$node\",link=~\"$link\",source=\"mac\"}[$__rate_interval])) or max by (node, link) (rate(mxl_gateway_link_transmitted_bytes_total{node=~\"$node\",link=~\"$link\",source=~\"rdma|netdev\"}[$__rate_interval]))))",
          "legendFormat": "",
          "instant": true,
          "range": false
        }
      ]
    },
    {
      "id": 5,
      "type": "stat",
      "title": "Hottest port vs ceiling",
      "description": "Highest committed demand on any port and direction over that port's plannable capacity (capacity times the node's maximum utilization). Above 100% placement has committed past the ceiling.",
      "datasource": {
        "type": "prometheus",
        "uid": "prometheus"
      },
      "gridPos": {
        "h": 4,
        "w": 4,
        "x": 12,
        "y": 1
      },
      "options": {
        "reduceOptions": {
          "calcs": [
            "lastNotNull"
          ],
          "fields": "",
          "values": false
        },
        "orientation": "auto",
        "colorMode": "background",
        "graphMode": "none",
        "textMode": "auto",
        "justifyMode": "auto"
      },
      "fieldConfig": {
        "defaults": {
          "unit": "percentunit",
          "thresholds": {
            "mode": "absolute",
            "steps": [
              {
                "color": "green",
                "value": null
              },
              {
                "color": "orange",
                "value": 0.9
              },
              {
                "color": "red",
                "value": 1
              }
            ]
          },
          "mappings": [],
          "color": {
            "mode": "thresholds"
          }
        },
        "overrides": []
      },
      "targets": [
        {
          "refId": "A",
          "datasource": {
            "type": "prometheus",
            "uid": "prometheus"
          },
          "expr": "max(mxl_operator_port_committed_bits_per_second{node=~\"$node\",port=~\"$port\",direction=~\"$direction\"} / on(node, port) group_left mxl_operator_port_plannable_bits_per_second{node=~\"$node\",port=~\"$port\"})",
          "legendFormat": "",
          "instant": true,
          "range": false
        }
      ]
    },
