      "targets": [
        {
          "refId": "A",
          "datasource": {
            "type": "prometheus",
            "uid": "prometheus"
          },
          "expr": "max(label_replace((8 * (sum by (node, link) (rate(mxl_gateway_link_received_bytes_total{node=~\"$node\",link=~\"$link\",source=\"mac\"}[$__rate_interval])) or max by (node, link) (rate(mxl_gateway_link_received_bytes_total{node=~\"$node\",link=~\"$link\",source=~\"rdma|netdev\"}[$__rate_interval])))) / on(node, link) mxl_gateway_link_speed_bits_per_second{node=~\"$node\",link=~\"$link\"}, \"direction\", \"ingress\", \"\", \"\") or label_replace((8 * (sum by (node, link) (rate(mxl_gateway_link_transmitted_bytes_total{node=~\"$node\",link=~\"$link\",source=\"mac\"}[$__rate_interval])) or max by (node, link) (rate(mxl_gateway_link_transmitted_bytes_total{node=~\"$node\",link=~\"$link\",source=~\"rdma|netdev\"}[$__rate_interval])))) / on(node, link) mxl_gateway_link_speed_bits_per_second{node=~\"$node\",link=~\"$link\"}, \"direction\", \"egress\", \"\", \"\"))",
          "legendFormat": "",
          "instant": true,
          "range": false
        }
      ]
    },
    {
      "id": 7,
      "type": "stat",
      "title": "Link errors",
      "description": "Error and drop counters of the selected links, per second, every source summed.",
